/** A dependency-free error shape for handling failures in Bollard integrations. */
export interface BollardErrorOptions extends ErrorOptions {
  code?: string
  retryable?: boolean
}

export class BollardError extends Error {
  readonly code: string
  readonly retryable: boolean

  constructor(message: string, options: BollardErrorOptions = {}) {
    super(message, options)
    this.name = "BollardError"
    this.code = options.code ?? "UNEXPECTED_ERROR"
    this.retryable = options.retryable ?? false
  }
}

/** Keep a safe, stable field message while retaining the original failure for diagnostics. */
export function toBollardError(
  cause: unknown,
  message = "Field validation failed. Try again.",
): BollardError {
  if (cause instanceof BollardError) return cause
  return new BollardError(message, {
    code: "VALIDATION_FAILED",
    retryable: true,
    cause,
  })
}

"use client"

// Bollard UI — use-bollard-field · MIT licence · https://bollard-ui.vercel.app/components/use-bollard-field

import * as React from "react"

import { createValidationRunner, getBollardAriaProps, type BollardValidator } from "./validation"
import type { BollardError } from "./error"

export { runBollardValidation } from "./validation"
export { getBollardAriaProps } from "./validation"
export { BollardError, toBollardError } from "./error"

export type { BollardValidator } from "./validation"
export type { BollardErrorOptions } from "./error"

export interface UseBollardFieldOptions<T> {
  /** The field's initial value. */
  initialValue: T
  /** Your validation logic. Sync functions and async checks are both supported. */
  validate: BollardValidator<T>
  /** Observe thrown validator failures (for logging or form-level recovery). */
  onError?: (error: BollardError) => void
}

export interface BollardField<T> {
  value: T
  /** Connect this to a control's onValueChange, onChange, or equivalent callback. */
  setValue: (value: T) => void
  /** Validate on blur and reveal the inline error. */
  onBlur: () => void
  error: string | undefined
  invalid: boolean
  isValidating: boolean
  errorId: string
  /** Spread onto the control to connect its accessible error state. */
  ariaProps: { "aria-invalid": true | undefined; "aria-describedby": string | undefined }
  /** Merge existing hint IDs with Bollard's error ID: `ariaPropsFor(hintId)`. */
  ariaPropsFor: (describedBy?: string) => { "aria-invalid": true | undefined; "aria-describedby": string | undefined }
  /** Set a server-side error; it clears when the user edits the value. */
  setError: (message: string) => void
  clearError: () => void
  /** Restore the initial value, or provide a new one. */
  reset: (value?: T) => void
  /** Run validation immediately. Resolves true if valid. */
  validate: () => Promise<boolean>
}

/**
 * Validation state for any React control. Bollard UI controls, shadcn/ui
 * controls and custom controls can all connect through `value`, `setValue`
 * and `ariaProps`; this hook renders no UI and has no styling dependency.
 */
export function useBollardField<T>({ initialValue, validate, onError }: UseBollardFieldOptions<T>): BollardField<T> {
  const [value, setValueState] = React.useState(initialValue)
  const [error, setErrorState] = React.useState<string>()
  const [touched, setTouched] = React.useState(false)
  const [isValidating, setIsValidating] = React.useState(false)
  const valueRef = React.useRef(value)
  const [runner] = React.useState(() => createValidationRunner(validate, (state) => {
    if (state.isValidating !== undefined) setIsValidating(state.isValidating)
    if ("error" in state) setErrorState(state.error)
  }, onError))
  const id = React.useId()
  const errorId = `bollard-${id.replace(/:/g, "")}-error`

  React.useEffect(() => {
    runner.setValidator(validate)
  }, [runner, validate])

  React.useEffect(() => {
    runner.setOnError(onError)
  }, [runner, onError])

  React.useEffect(() => {
    valueRef.current = value
  }, [value])

  const setValue = React.useCallback((nextValue: T) => {
    runner.invalidate()
    valueRef.current = nextValue
    setValueState(nextValue)
    // A server/previous error shouldn't stick after the user changes the value.
    setErrorState(undefined)
    if (touched) void runner.validate(nextValue)
  }, [runner, touched])

  const onBlur = React.useCallback(() => {
    setTouched(true)
    void runner.validate(valueRef.current)
  }, [runner])

  const setError = React.useCallback((message: string) => {
    runner.invalidate()
    setIsValidating(false)
    setErrorState(message)
  }, [runner])

  const clearError = React.useCallback(() => {
    runner.invalidate()
    setIsValidating(false)
    setErrorState(undefined)
  }, [runner])

  const reset = React.useCallback((nextValue: T = initialValue) => {
    runner.invalidate()
    valueRef.current = nextValue
    setValueState(nextValue)
    setErrorState(undefined)
    setTouched(false)
    setIsValidating(false)
  }, [initialValue, runner])

  const invalid = Boolean(error)
  return {
    value,
    setValue,
    onBlur,
    error,
    invalid,
    isValidating,
    errorId,
    ariaProps: getBollardAriaProps(errorId, error),
    ariaPropsFor: (describedBy) => getBollardAriaProps(errorId, error, describedBy),
    setError,
    clearError,
    reset,
    validate: async () => !(await runner.validate(valueRef.current)),
  }
}

// Bollard UI — use-bollard-field · MIT licence · https://bollard-ui.vercel.app/components/use-bollard-field

import { toBollardError, type BollardError } from "./error"

/** Return a message when a value is invalid, or nothing when it is valid. */
export type BollardValidator<T> = (value: T) => string | undefined | Promise<string | undefined>

export interface ValidationStateUpdate {
  error?: string
  isValidating: boolean
}

/** Merge Bollard's error relationship with IDs already used by a control. */
export function getBollardAriaProps(errorId: string, error?: string, describedBy?: string) {
  const ids = new Set((describedBy ?? "").split(/\s+/).filter(Boolean))
  if (error) ids.add(errorId)
  return {
    "aria-invalid": error ? true as const : undefined,
    "aria-describedby": ids.size ? [...ids].join(" ") : undefined,
  }
}

/** Normalize sync and async validators to one promise-based API. */
export async function runBollardValidation<T>(validator: BollardValidator<T>, value: T) {
  const message = await validator(value)
  return typeof message === "string" && message.trim() ? message : undefined
}

/**
 * Coordinates async field checks without React or UI dependencies. Only the
 * newest request may publish state; invalidating a request prevents stale
 * results from restoring an error after the user edits or resets the field.
 */
export function createValidationRunner<T>(
  validator: BollardValidator<T>,
  onState: (state: ValidationStateUpdate) => void,
  onError?: (error: BollardError) => void,
) {
  let currentValidator = validator
  let currentOnError = onError
  let requestId = 0

  return {
    setValidator(next: BollardValidator<T>) {
      currentValidator = next
      requestId += 1
      onState({ isValidating: false })
    },
    setOnError(next?: (error: BollardError) => void) {
      currentOnError = next
    },
    invalidate() {
      requestId += 1
      onState({ isValidating: false })
    },
    async validate(value: T) {
      const thisRequest = ++requestId
      onState({ isValidating: true })
      let error: string | undefined
      try {
        error = await runBollardValidation(currentValidator, value)
      } catch (cause) {
        error = "Unable to validate this value. Try again."
        if (thisRequest === requestId) {
          try {
            currentOnError?.(toBollardError(cause))
          } catch {
            // Consumer diagnostics must not break the field's recoverable state.
          }
        }
      }
      if (thisRequest === requestId) onState({ error, isValidating: false })
      return error
    },
  }
}
